/**
 * A world<-camera pose. `r` is row-major 3x3, matching PLAN.md §5.
 */
public struct FfiPose {
    public var r: [Float]
    public var t: FfiVec3

    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(r: [Float], t: FfiVec3) {
        self.r = r
        self.t = t
    }
}



extension FfiPose: Equatable, Hashable {
    public static func ==(lhs: FfiPose, rhs: FfiPose) -> Bool {
        if lhs.r != rhs.r {
            return false
        }
        if lhs.t != rhs.t {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(r)
        hasher.combine(t)
    }
}


