/**
 * Errors the clients have to handle rather than crash on.
 */
public enum FfiError {

    
    
    case BadPose(count: UInt32
    )
    case LengthMismatch(points: UInt32, normals: UInt32
    )
}


#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeFfiError: FfiConverterRustBuffer {
    typealias SwiftType = FfiError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> FfiError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .BadPose(
            count: try FfiConverterUInt32.read(from: &buf)
            )
        case 2: return .LengthMismatch(
            points: try FfiConverterUInt32.read(from: &buf), 
            normals: try FfiConverterUInt32.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .BadPose(count):
            writeInt(&buf, Int32(1))
            FfiConverterUInt32.write(count, into: &buf)
            
        
        case let .LengthMismatch(points,normals):
            writeInt(&buf, Int32(2))
            FfiConverterUInt32.write(points, into: &buf)
            FfiConverterUInt32.write(normals, into: &buf)
            
        }
    }
}


